//! 🧾️ Original export metadata is copied incrementally and transferred into the supplied output publication.
use semio_s_artifact_layout_layout_engine_export::LayoutExportKind;
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,retained_clone_grant_admits}};
#[derive(Clone,Copy)]pub struct LayoutExportMetadataInput<'a>{pub kind:LayoutExportKind,pub name:&'a str,pub page_id:Option<&'a str>,pub document_id:&'a str,pub revision:&'a[u8;32]}
#[derive(semio_framework_value::RetireOwned)]pub struct PreparedLayoutExportMetadata{pub page_id:Option<String>,pub parent_document_id:String,pub canonical_base_revision_hex:String,pub filename:String,pub mime_type:String,pub encoding:Option<String>}
#[derive(Clone,Copy,PartialEq,Eq)]enum Phase{Bind,Fields,Ready,Closed}
pub struct LayoutExportMetadataCursor{fields:[Vec<u8>;6],lengths:[usize;6],keys:[usize;8],revision:[u8;32],kind:LayoutExportKind,phase:Phase,field:usize,offset:usize,name_at:usize,name_count:usize,suffix:bool,page:bool,binary:bool,closing:bool}
pub struct LayoutExportMetadataAdvance{pub progress:RetainedCloneProgress,pub done:bool}
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl LayoutExportMetadataCursor{
 const HEADER:usize=2*std::mem::size_of::<Self>();
 pub fn birth_demand()->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn admit(g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{let d=Self::birth_demand();if !retained_clone_grant_admits(g,d){return Err(refusal("layout export metadata birth is unfunded"))}Ok((Self{fields:std::array::from_fn(|_|Vec::new()),lengths:[0;6],keys:[0;8],revision:[0;32],kind:LayoutExportKind::Svg,phase:Phase::Bind,field:0,offset:0,name_at:0,name_count:0,suffix:false,page:false,binary:false,closing:false},RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 fn keys(input:LayoutExportMetadataInput<'_>)->[usize;8]{[input.name.as_ptr()as usize,input.name.len(),input.page_id.map_or(0,|page|page.as_ptr()as usize),input.page_id.map_or(0,str::len),input.document_id.as_ptr()as usize,input.document_id.len(),input.revision.as_ptr()as usize,input.kind as usize]}
 pub fn next_demand(&self,input:LayoutExportMetadataInput<'_>)->Result<RetirementDemand,ValueError>{if self.closing||self.phase==Phase::Closed{return Err(refusal("layout export metadata cursor is closing"))}if self.phase!=Phase::Bind&&(self.keys!=Self::keys(input)||self.revision!=*input.revision){return Err(refusal("layout export metadata original source changed"))}let capacity_bytes=if self.phase==Phase::Fields&&self.fields[self.field].capacity()<self.lengths[self.field]{self.lengths[self.field]}else{0};Ok(RetirementDemand{capacity_bytes,..Self::birth_demand()})}
 pub fn advance(&mut self,input:LayoutExportMetadataInput<'_>,g:RetainedCloneGrant)->Result<LayoutExportMetadataAdvance,ValueError>{let d=self.next_demand(input)?;if !retained_clone_grant_admits(g,d){return Ok(LayoutExportMetadataAdvance{progress:Default::default(),done:false})}let mut progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if self.phase==Phase::Bind{if input.page_id.is_some_and(|page|page.len()>256)||input.document_id.len()>256{return Err(refusal("layout export metadata authority exceeds its source bound").with_retained_progress(progress))}self.keys=Self::keys(input);self.revision=*input.revision;self.kind=input.kind;self.page=input.page_id.is_some();self.binary=input.kind.binary();self.lengths=[input.page_id.map_or(0,str::len),input.document_id.len(),64,128+1+input.kind.extension().len(),input.kind.mime_type().len(),if self.binary{6}else{0}];self.phase=Phase::Fields;return Ok(LayoutExportMetadataAdvance{progress,done:false})}if self.phase==Phase::Ready{return Ok(LayoutExportMetadataAdvance{progress,done:true})}if d.capacity_bytes>0{self.fields[self.field].try_reserve_exact(d.capacity_bytes).map_err(|_|refusal("layout export metadata backing allocation refused").with_retained_progress(progress))?;progress.retained_capacity_bytes=self.fields[self.field].capacity();return Ok(LayoutExportMetadataAdvance{progress,done:false})}
 let content=match self.field{0=>Some(input.page_id.unwrap_or("")),1=>Some(input.document_id),4=>Some(self.kind.mime_type()),5=>Some(if self.binary{"base64"}else{""}),_=>None};if let Some(content)=content{if self.offset==content.len(){self.field+=1;self.offset=0}else{self.fields[self.field].push(content.as_bytes()[self.offset]);self.offset+=1}}else if self.field==2{if self.offset==64{self.field+=1;self.offset=0}else{let byte=input.revision[self.offset/2];let n=if self.offset%2==0{byte>>4}else{byte&15};self.fields[2].push(if n<10{b'0'+n}else{b'a'+n-10});self.offset+=1}}else{let name=if self.kind==LayoutExportKind::Package{input.name}else{input.page_id.unwrap_or(input.name)};if !self.suffix{if name.is_empty(){if self.name_count<6{self.fields[3].push(b"layout"[self.name_count]);self.name_count+=1;return Ok(LayoutExportMetadataAdvance{progress,done:false})}}else if self.name_at<name.len()&&self.name_count<128{let character=name.get(self.name_at..).and_then(|tail|tail.chars().next()).ok_or_else(||refusal("layout export filename source boundary differs").with_retained_progress(progress))?;self.name_at+=character.len_utf8();self.name_count+=1;self.fields[3].push(if character.is_ascii_alphanumeric()||matches!(character,'-'|'_'|'.'){character as u8}else{b'-'});return Ok(LayoutExportMetadataAdvance{progress,done:false})}self.fields[3].push(b'.');self.suffix=true;self.offset=0}else if self.offset<self.kind.extension().len(){self.fields[3].push(self.kind.extension().as_bytes()[self.offset]);self.offset+=1}else{self.field+=1;self.offset=0}}if self.field==6{self.phase=Phase::Ready}Ok(LayoutExportMetadataAdvance{progress,done:false})}
 pub fn ready(&self)->bool{self.phase==Phase::Ready&&!self.closing}
 pub fn take_ready_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER+2*std::mem::size_of::<PreparedLayoutExportMetadata>()+self.fields.iter().map(Vec::len).sum::<usize>(),depth:1,..Default::default()}}
 pub fn take_ready(&mut self,g:RetainedCloneGrant)->Result<Option<(PreparedLayoutExportMetadata,RetainedCloneProgress)>,ValueError>{if !self.ready(){return Err(refusal("layout export metadata is not ready"))}let d=self.take_ready_demand();if !retained_clone_grant_admits(g,d){return Ok(None)}let progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};for field in &self.fields{if std::str::from_utf8(field).is_err(){return Err(refusal("layout export metadata source no longer forms original UTF8").with_retained_progress(progress))}}let [page,parent,revision,filename,mime,encoding]=std::mem::take(&mut self.fields).map(validated_string);self.phase=Phase::Closed;self.keys=[0;8];let value=PreparedLayoutExportMetadata{page_id:self.page.then_some(page),parent_document_id:parent,canonical_base_revision_hex:revision,filename,mime_type:mime,encoding:self.binary.then_some(encoding)};Ok(Some((value,progress)))}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self)->RetirementDemand{if self.phase==Phase::Closed{Default::default()}else{RetirementDemand{release_bytes:self.fields.iter().find(|field|field.capacity()>0).map_or(0,Vec::capacity),..Self::birth_demand()}}}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if !self.closing{return Err(refusal("layout export metadata closure has not begun"))}let d=self.close_demand();if self.phase==Phase::Closed||!retained_clone_grant_admits(g,d){return Ok(Default::default())}if let Some(field)=self.fields.iter_mut().find(|field|field.capacity()>0){drop(std::mem::take(field))}else{self.keys=[0;8];self.phase=Phase::Closed}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})}
 pub fn terminal_is_empty(&self)->bool{self.phase==Phase::Closed&&self.fields.iter().all(|field|field.capacity()==0)}
}
/// 🪶️ Every transferred allocation was checked as complete UTF8 in the same exclusive funded take turn.
fn validated_string(bytes:Vec<u8>)->String{unsafe{String::from_utf8_unchecked(bytes)}}
